import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Sources & Coverage","description":"A page-by-page mapping of the Hearth roadmap, ten volumes, build-vs-integrate note, and volume README to this site.","frontmatter":{"title":"Sources & Coverage","description":"A page-by-page mapping of the Hearth roadmap, ten volumes, build-vs-integrate note, and volume README to this site.","outline":[2,3]},"headers":[],"relativePath":"en/reference/source-map.md","filePath":"en/reference/source-map.md","lastUpdated":null}'),o={name:"en/reference/source-map.md"};function i(s,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[n(`<p class="eyebrow">SOURCES &amp; COVERAGE</p><h1 id="sources-coverage" tabindex="-1">Sources &amp; Coverage <a class="header-anchor" href="#sources-coverage" aria-label="Permalink to &quot;Sources &amp; Coverage&quot;">​</a></h1><p class="lead">This site is not a set of disconnected articles; it is a topic-based reorganization of the original roadmap material. This page shows where every source document lives and which original conclusions are preserved.</p><h2 id="coverage-result" tabindex="-1">Coverage Result <a class="header-anchor" href="#coverage-result" aria-label="Permalink to &quot;Coverage Result&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audit item</th><th>Result</th></tr></thead><tbody><tr><td>Source material</td><td>One complete master document, ten volumes, one build-vs-integrate note, and one volume README</td></tr><tr><td>Ten volumes</td><td>Every substantive block is present verbatim in the Chinese site; coverage is 100%</td></tr><tr><td>Complete master document</td><td>595/595 substantive blocks preserved; coverage is 100%</td></tr><tr><td>Build-vs-integrate note</td><td>67/67 substantive blocks preserved; coverage is 100%</td></tr><tr><td>Bilingual structure</td><td>Every Chinese page has an English page with a matching path and heading hierarchy</td></tr></tbody></table><p>The audit works at the level of substantive blocks, not sampled character counts. The original long-form document also remains in the <a href="/hearth-os/en/reference/full-roadmap.html">full roadmap archive</a>. Topic pages reduce reading cost; the archive preserves complete detail.</p><h2 id="original-volume-readme-conclusions-and-reading-paths" tabindex="-1">Original Volume README: Conclusions and Reading Paths <a class="header-anchor" href="#original-volume-readme-conclusions-and-reading-paths" aria-label="Permalink to &quot;Original Volume README: Conclusions and Reading Paths&quot;">​</a></h2><p>Hearth is a single-user, self-hosted, long-running, low-interruption, low-Token general-purpose personal Agent OS. Its core is not &quot;another model&quot;; it is task control, durable execution, memory, verification, approvals, receipts, and a quiet task-card experience.</p><p>The roadmap rests on three core principles:</p><ol><li><strong>Build the smallest product first, then the complete OS.</strong> A daily-usable MVP must appear inside Stage 1, not wait until Stage 6.</li><li><strong>The frontend exists from day one.</strong> Stage 0 has a clickable prototype, and Stage 1 has real Web task cards; every increment needs a user-visible path, verification, and recovery.</li><li><strong>Stop planning by week or month.</strong> Chapter 25 is the complete Stage 0–6 progressive development sequence, driven only by capability gates and with no development time limit.</li></ol><h3 id="product-and-decision-path" tabindex="-1">Product and Decision Path <a class="header-anchor" href="#product-and-decision-path" aria-label="Permalink to &quot;Product and Decision Path&quot;">​</a></h3><p>For a first introduction to the project, or when deciding whether to continue investing:</p><ol><li><a href="/hearth-os/en/product/definition.html">Product Definition and Design Judgment</a></li><li><a href="/hearth-os/en/delivery/roadmap.html">Phased Product Roadmap</a></li><li><a href="/hearth-os/en/delivery/development-plan.html">From 0 to 100 Development Plan</a></li><li><a href="/hearth-os/en/delivery/engineering.html">Engineering Delivery, Risk, and Decisions</a></li></ol><h3 id="architecture-and-technology-path" tabindex="-1">Architecture and Technology Path <a class="header-anchor" href="#architecture-and-technology-path" aria-label="Permalink to &quot;Architecture and Technology Path&quot;">​</a></h3><p>For preparing implementation or checking system boundaries:</p><ol><li><a href="/hearth-os/en/architecture/overview.html">Overall Architecture and Domain Protocols</a></li><li><a href="/hearth-os/en/architecture/control-plane.html">Entry, Control Plane, and Durable Execution</a></li><li><a href="/hearth-os/en/architecture/executor-model.html">Executor System and Human Takeover</a></li><li><a href="/hearth-os/en/architecture/execution-safety.html">Execution Safety, Memory, and Evolution</a></li><li><a href="/hearth-os/en/architecture/token-economics.html">Token Economics and Frontend Experience</a></li><li><a href="/hearth-os/en/architecture/security-privacy.html">Security, Privacy, and Evaluation</a></li></ol><h3 id="direct-build-path" tabindex="-1">Direct Build Path <a class="header-anchor" href="#direct-build-path" aria-label="Permalink to &quot;Direct Build Path&quot;">​</a></h3><p>For readers ready to create the repository:</p><ol><li>The MVP and Stage 1 sections of the <a href="/hearth-os/en/delivery/development-plan.html">From 0 to 100 Development Plan</a></li><li><a href="/hearth-os/en/architecture/domain-model.html">Overall Architecture and Domain Protocols</a></li><li><a href="/hearth-os/en/architecture/durable-execution.html">Entry, Control Plane, and Durable Execution</a></li><li><a href="/hearth-os/en/delivery/engineering.html">Engineering Delivery, Risk, and Decisions</a></li></ol><h2 id="source-material-to-site-pages" tabindex="-1">Source Material to Site Pages <a class="header-anchor" href="#source-material-to-site-pages" aria-label="Permalink to &quot;Source Material to Site Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Volume</th><th>Corresponding master chapters</th><th>What you can answer after reading</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/product/definition.html">01 Product Definition and Design Judgment</a></td><td>Chapters 0–3</td><td>Who Hearth is for, what it does, what it does not do, and why it is not a Codex wrapper</td></tr><tr><td><a href="/hearth-os/en/architecture/overview.html">02 Overall Architecture and Domain Protocols</a></td><td>Chapters 4–5</td><td>How the seven planes cooperate and what the core entities and protocols are</td></tr><tr><td><a href="/hearth-os/en/architecture/gateway.html">03 Entry, Control Plane, and Durable Execution</a></td><td>Chapters 6–8</td><td>How events enter, how they are authorized, and how execution and recovery stay reliable</td></tr><tr><td><a href="/hearth-os/en/architecture/executor-model.html">04 Executor System and Human Takeover</a></td><td>Chapters 9–16</td><td>How Codex, Native, Connector, Browser, GUI, Document/Data, and Human divide work</td></tr><tr><td><a href="/hearth-os/en/architecture/execution-safety.html">05 Execution Safety, Memory, and Evolution</a></td><td>Chapters 17–19</td><td>How Sandbox, credentials, side effects, memory, and skill evolution stay controlled</td></tr><tr><td><a href="/hearth-os/en/architecture/token-economics.html">06 Token Economics and Frontend Experience</a></td><td>Chapters 20–21</td><td>How Tokens are controlled and why users only see tasks</td></tr><tr><td><a href="/hearth-os/en/architecture/security-privacy.html">07 Security, Privacy, and Evaluation</a></td><td>Chapters 22–23</td><td>The trust boundaries, threat model, evaluation, and stage gates</td></tr><tr><td><a href="/hearth-os/en/delivery/roadmap.html">08 Phased Product Roadmap</a></td><td>Chapter 24</td><td>What Stages 0–6 deliver and when each is complete</td></tr><tr><td><a href="/hearth-os/en/delivery/development-plan.html">09 From 0 to 100 Development Plan</a></td><td>Chapter 25</td><td>The build order, MVP contents, and acceptance method for each increment</td></tr><tr><td><a href="/hearth-os/en/delivery/engineering.html">10 Engineering Delivery, Risk, and Decisions</a></td><td>Chapters 26–29</td><td>How to lay out the repository, when to stop, and the ADRs and final judgment</td></tr></tbody></table><h3 id="additional-sources" tabindex="-1">Additional Sources <a class="header-anchor" href="#additional-sources" aria-label="Permalink to &quot;Additional Sources&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>Site entry</th><th>Treatment</th></tr></thead><tbody><tr><td>Complete master document</td><td><a href="/hearth-os/en/reference/full-roadmap.html">Full Roadmap Archive</a></td><td>Preserves every detail for search, citation, and difference checks</td></tr><tr><td>Build-vs-integrate note</td><td><a href="/hearth-os/en/reference/build-vs-integrate.html">Build vs. Integrate Boundary</a></td><td>Preserves the boundary conclusions, OpenClaw comparison, and Codex integration rules</td></tr><tr><td>Volume README</td><td><a href="/hearth-os/en/guide/">Start Reading</a>, <a href="/hearth-os/en/guide/reading-guide.html">Reading Guide</a>, and this page</td><td>Preserves conclusions, three reading paths, the ten-volume catalog, and the one-page map</td></tr></tbody></table><h2 id="one-page-map-from-0-to-100" tabindex="-1">One-Page Map from 0 to 100 <a class="header-anchor" href="#one-page-map-from-0-to-100" aria-label="Permalink to &quot;One-Page Map from 0 to 100&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Stage 0  Product wedge + clickable prototype + protocol/evaluation baseline</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 1  Walking skeleton → first real Codex slice → MVP → side-effect safety → second task family</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 2  Read-only connectors → docs/data → browser → drafts/approvals/receipts → daily operator</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 3  Device agentd → observe/takeover → low-risk GUI → high-risk GUI</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 4  Trigger/proactive inbox → mobile PWA → secure pairing → attention budget</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 5  Memory Core → forgetting/export → skill candidates/evaluation → promotion/rollback</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 6  Multi-device sync → offline queue → revocation/keys → backup migration → v1.0</span></span></code></pre></div><p>&quot;100%&quot; does not mean never iterating again; it is the v1.0 exit of Stage 6: a complete product that is recoverable, approvable, portable, revocable, and usable long term.</p><h2 id="coverage-and-maintenance-rules" tabindex="-1">Coverage and Maintenance Rules <a class="header-anchor" href="#coverage-and-maintenance-rules" aria-label="Permalink to &quot;Coverage and Maintenance Rules&quot;">​</a></h2><ul><li><strong>The master document</strong> preserves every detail; volumes support topic-by-topic reading and do not replace it.</li><li>Every volume states its corresponding master chapters and prerequisite reading at the top.</li><li>&quot;Stage&quot; is a capability level, not a date; an &quot;increment&quot; is a development unit, not a schedule commitment.</li><li>Every stage gate must include user-visible UI, durable state, verification evidence, and recovery paths.</li><li>Capabilities that exist only in a CLI, log, or database do not count as stage completion.</li></ul><p>When source documents change, update the topic pages, complete archive, and English mirror together. The coverage audit script lives at <code>scripts/check-coverage.py</code>; it must never be weakened by deleting source prose.</p>`,29)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
